<script setup lang="ts">
import { errorMessage } from '@/utils'
import {onMounted,ref} from 'vue'
import type {ProjectPreferences} from '@/types/project'
const value=ref<ProjectPreferences>({maxTurns:8,contextMessages:12,defaultSource:'unknown',defaultState:'active',defaultTab:'timeline'}),error=ref(''),saved=ref(false),busy=ref(false)
onMounted(async()=>{try{value.value=await window.baoyi.project.preferences()}catch(e){error.value=errorMessage(e)}})
async function save(){if(busy.value)return;busy.value=true;saved.value=false;error.value='';try{value.value=await window.baoyi.project.preferences(JSON.parse(JSON.stringify(value.value)));saved.value=true}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
</script>
<template><div class="project-settings"><section><h2>{{ $t("项目助手") }}</h2><p>{{ $t("围绕当前项目连续对话，查看目录、说明与 Git 状态，整理项目资料。") }}</p><p class="hint">{{ $t("使用上方选择的模型。对话时，项目资料及助手读取的文本会发送给该模型服务。") }}</p><label>{{ $t("每次对话最多调用轮数") }}<input v-model.number="value.maxTurns" type="number" min="2" max="20"/></label><p class="hint">{{ $t("完整记录保存在本地。长会话使用近期原文和可查询的历史索引，达到轮数或上下文预算后保留检查点，可继续。") }}</p></section><section><h2>{{ $t("进入项目时") }}</h2><label>{{ $t("默认打开栏目") }}<select v-model="value.defaultTab" :aria-label="$t('项目默认栏目')"><option value="timeline">{{ $t("项目日志") }}</option><option value="overview">{{ $t("工作区概览") }}</option><option value="chat">{{ $t("项目助手") }}</option><option value="entries">{{ $t("项目入口") }}</option><option value="info">{{ $t("项目资料") }}</option></select></label><p class="hint">{{ $t("从项目库打开时使用此栏目；带有明确栏目或会话的链接优先。") }}</p></section><section><h2>{{ $t("新项目默认值") }}</h2><label>{{ $t("来源") }}<select v-model="value.defaultSource"><option value="unknown">{{ $t("来源未标记") }}</option><option value="self">{{ $t("自己建立") }}</option><option value="third-party">{{ $t("第三方项目") }}</option><option value="mixed">{{ $t("混合来源") }}</option></select></label><label>{{ $t("状态") }}<select v-model="value.defaultState"><option value="active">{{ $t("使用中") }}</option><option value="maintaining">{{ $t("维护中") }}</option><option value="paused">{{ $t("已暂停") }}</option><option value="archived">{{ $t("已归档") }}</option></select></label></section><p v-if="error" role="alert">{{$systemMessage(error)}}</p><div class="settings-actions"><button class="btn btn--primary" :disabled="busy" @click="save">{{ $t("保存项目偏好") }}</button><span v-if="saved" role="status">{{ $t("已保存") }}</span></div></div></template>
<style scoped>.project-settings{max-width:850px}.project-settings section{background:var(--bg-card);border:1px solid var(--divider);border-radius:10px;padding:24px;margin-bottom:22px}.project-settings h2{font-size:18px;margin:0 0 12px}.project-settings p{color:var(--text-sub);line-height:1.8;font-size:13px}.project-settings label{display:flex;align-items:center;justify-content:space-between;gap:20px;max-width:580px;padding:12px 0;font-size:14px}.project-settings input,.project-settings select{width:180px;border:1px solid var(--divider);background:var(--bg-input);padding:9px;border-radius:6px}.model-status{display:flex;gap:20px;align-items:center;color:var(--accent)}.settings-actions{display:flex;align-items:center;gap:15px}.settings-actions span{font-size:13px;color:var(--accent)}</style>
